@@ -1,11 +1,27 @@
+function asRecord(value: unknown): Record<string, unknown> | null {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    return null;
+  }
+  return value as Record<string, unknown>;
+}
+
+const ROUND_BRANCH = /^agent\/rounds-(\d+)$/;
+const RETRY_BRANCH = /^[a-z][a-z0-9-]{0,19}\/[a-z0-9-]+-retry$/;
+
 export function parseRoundBranch(branch: unknown): number | null {
-  void branch;
-  throw new Error("not implemented");
+  if (typeof branch !== "string") {
+    return null;
+  }
+  const match = ROUND_BRANCH.exec(branch);
+  if (match === null) {
+    return null;
+  }
+  const round = Number(match[1]);
+  return round >= 1 ? round : null;
 }

 export function isRetryBranch(branch: unknown): boolean {
-  void branch;
-  throw new Error("not implemented");
+  return typeof branch === "string" && RETRY_BRANCH.test(branch);
 }

 export function summarizeRounds(branches: unknown): {
@@ -13,6 +29,19 @@ export function summarizeRounds(branches: unknown): {
   retries: number;
   max_round: number | null;
 } {
-  void branches;
-  throw new Error("not implemented");
+  const out = { rounds: 0, retries: 0, max_round: null as number | null };
+  if (!Array.isArray(branches)) {
+    return out;
+  }
+  for (const branch of branches) {
+    const round = parseRoundBranch(branch);
+    if (round !== null) {
+      out.rounds += 1;
+      out.max_round = out.max_round === null ? round : Math.max(out.max_round, round);
+    }
+    if (isRetryBranch(branch)) {
+      out.retries += 1;
+    }
+  }
+  return out;
 }

